import{_ as t,c as e,a2 as l,o as a}from"./chunks/framework.CO0qOYmW.js";const g=JSON.parse('{"title":"工程化面试题","description":"","frontmatter":{"title":"工程化面试题","category":"面试题","excerpt":"Vite Webpack 1. 底层架构 ： 开发模式 ：基于打包器的架构，每次启动或修改代码时，Webpack 需要递归分析依赖关系，构建完整的依赖图，并将所有模块打包成一个或多个 Bundle（即使只改了一个文件）。 webpack基于..."},"headers":[],"relativePath":"interview/08-engineering.md","filePath":"interview/08-engineering.md","lastUpdated":1773591891000}'),o={name:"interview/08-engineering.md"};function r(s,i,n,c,p,u){return a(),e("div",null,i[0]||(i[0]=[l('<h1 id="工程化面试题" tabindex="-1">工程化面试题 <a class="header-anchor" href="#工程化面试题" aria-label="Permalink to &quot;工程化面试题&quot;">​</a></h1><h2 id="_1-vite为什么比webpack快" tabindex="-1">1. vite为什么比webpack快？ <a class="header-anchor" href="#_1-vite为什么比webpack快" aria-label="Permalink to &quot;1. vite为什么比webpack快？&quot;">​</a></h2><div class="tip custom-block github-alert"><p class="custom-block-title">Vite</p><p>[!tip] Webpack <strong>1. 底层架构</strong> ：</p><ul><li>开发模式 ：基于打包器的架构，每次启动或修改代码时，Webpack 需要递归分析依赖关系，构建完整的依赖图，并将所有模块打包成一个或多个 Bundle（即使只改了一个文件）。</li><li>webpack基于模块化，vite基于编译时编译。利用浏览器原生支持 ES Modules的特性，直接按需加载源码文件，无需打包。 <strong>2. 开发环境的优化</strong>：</li></ul></div><div class="tip custom-block github-alert"><p class="custom-block-title">Vite</p><p><strong>1. 底层架构</strong> ：</p><ul><li>开发模式 ： 基于原生 ESM 的按需编译架构，只编译当前文件和它的依赖，并将它们组合成一个 Bundle。 <strong>2. 开发环境的优化</strong>：核心是依赖现代浏览器对原生 ES 模块 (import/export) 的支持。</li><li>启动服务器：不需要预先打包任何东西，只需要启动一个基于原生 ES 模块的服务器。</li><li>按需编译：当浏览器请求某个模块时，Vite 的服务器才会按需编译这个模块（以及它依赖的裸模块）。</li><li>编译完成后，将结果以原生 ESM 格式返回给浏览器。浏览器根据 import 语句自行发起后续依赖请求。</li></ul><ol start="3"><li><strong>更快的热更新：</strong></li></ol><ul><li>Vite 使用原生 ESM 格式，浏览器原生支持，无需打包，因此热更新速度更快。</li><li>未修改的模块请求会直接返回 304 Not Modified，浏览器使用缓存。</li><li>因为模块是独立请求和编译的，Vite 可以精确地使 HMR 的边界只限于被修改的模块及其直接依赖。</li></ul><ol start="4"><li><strong>预构建依赖：</strong></li></ol><ul><li>Vite 可以预构建依赖，并将它们缓存到本地，下次启动时直接加载缓存。</li><li>预构建依赖可以加速开发环境的启动时间，缩短开发周期。</li></ul><ol start="5"><li><strong>更好的错误提示：</strong></li></ol><ul><li>Vite 使用原生 ESM 格式，浏览器原生支持，因此错误提示更准确。</li><li>Vite 会在编译时捕获语法错误和类型错误，并在浏览器中显示详细的错误信息。</li></ul></div><h2 id="_2-你是如何理解工程化的" tabindex="-1">2. 你是如何理解工程化的？ <a class="header-anchor" href="#_2-你是如何理解工程化的" aria-label="Permalink to &quot;2. 你是如何理解工程化的？&quot;">​</a></h2><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>工程化是一种思想，而不是一种工具或方法。工程化的核心是通过自动化、标准化和流程化来提升效率、降低成本、提升质量。 工程化的目标是通过一系列流程和工具来提升软件开发的效率、质量和可维护性。 工程化的实践可分为：</p><ul><li>工具化：通过构建工具、自动化工具和包管理工具来简化和加速开发流程。</li><li>流程化：通过引入持续集成（CI）、持续部署（CD）等流程，确保代码在开发、测试和部署阶段的质量和一致性。</li><li>规范化：通过制定代码风格、命名规范、文档模板等标准，确保代码的可读性、可维护性和可扩展性。</li></ul></div>',6)]))}const b=t(o,[["render",r]]);export{g as __pageData,b as default};
